{
  "packet_id": "H6-T01-3",
  "claim_id": "C054",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C054.component",
    "value": "Before launch, the trial should have a specified duration, comparable bookings, success criterion and acceptable workload and access effects.",
    "scope": "A prospective trial-design requirement; the mapping does not supply the actual duration, criteria or acceptable-effect thresholds.",
    "provenance": {
      "refs": [
        {
          "source_id": "P033",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P033 directly supplies all listed pre-launch requirements."
    }
  },
  "signal_basis": {
    "component_id": "C054.signal_basis",
    "value": "The mapping selects a narrowly scoped, reversible trial, observes delays, booking displacement and workload or cleaning effects, and compares outcomes with comparable baseline bookings. Improvement supports further testing without establishing causation, and inadequate comparable observations preclude declaring success or failure.",
    "scope": "Prospective evaluation of the selected trial, accounting for equipment, crew and demand differences.",
    "provenance": {
      "refs": [
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P021",
          "role": "SUPPORT"
        },
        {
          "source_id": "P027",
          "role": "SUPPORT"
        },
        {
          "source_id": "P035",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans specify the trial, observed outcomes, comparison requirements and limits on interpreting improvement or insufficient observations."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C054.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported as a procedural evaluation requirement; no unresolved empirical relation is needed."
    }
  },
  "rationale": "The proposed outcome comparison warrants specifying the observation period, comparison bookings and decision criteria before launch. Monitoring workload and booking displacement likewise warrants defining acceptable effects beforehand. This licenses the stated design requirement without establishing particular thresholds, sufficient sample size or trial effectiveness.",
  "uncertainty": "The mapping leaves the actual duration, success criterion and acceptable-effect thresholds unspecified, as the frozen claim explicitly acknowledges.",
  "anomalies": []
}
